javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let recordType = "incident";
    if (api.context.props.fields.major_incident_state) {
        if (api.context.props.fields.major_incident_state.originalValue == "proposed") {
            recordType = "mi-candidate";
        } else if (api.context.props.fields.major_incident_state.originalValue == "accepted") {
            recordType = "major-incident";
        }
    }

    return {
        event: "Edit Impact Summary",
        value: {
            "User": api.context.session.user.sys_id,
            "Type": recordType
        }
    };
})

